node --input-type=module <<'JS'
import {frozenStudy} from './research/robustness/h8/frozen-study.mjs';
import {spawnSync} from 'node:child_process';
const replay=frozenStudy();
try {
 const outcome=spawnSync(process.execPath,[replay.command,'--synthetic'],{encoding:'utf8'});
 if(outcome.status!==0)throw new Error(outcome.stderr);
 const data=JSON.parse(outcome.stdout);
 console.log(JSON.stringify(data,null,2));
} finally { replay.cleanup(); }
